<script setup>
import {useDramaI18n} from './useDramaI18n.js';
const {language,tr}=useDramaI18n();
import DramaMySubmissions from './DramaMySubmissions.vue';
import {computed,ref} from 'vue';import {attendance} from '../utils/calendarDisplay';import {useEventsStore} from '../stores/events';import {projectPersonalCalendar,filterPersonalCalendar} from './personalCalendar.js';import {activityCategory,activityLabel} from '../utils/activityTypes';
const props=defineProps({snapshot:Object,loadError:String});const emit=defineEmits(['open']);const data=useEventsStore(),channels=ref(['offline','live','drama']);
const rows=computed(()=>projectPersonalCalendar({events:data.records.filter(e=>e.kind==='event'),dramas:props.snapshot?.dramas||[],changes:props.snapshot?.changes||[],eventIds:[...data.favorites,...data.myItems],dramaIds:data.favorites.filter(id=>id.startsWith('drama:')).map(id=>id.slice(6)),classifyEvent:e=>attendance(e.city)==='online'||activityCategory(e.activity_type!=='other'?e.activity_type:e.type)==='broadcast'?'live':'offline'}));const visible=computed(()=>filterPersonalCalendar(rows.value,channels.value));
</script><template><section><p>{{tr('汇总已收藏活动、个人事项及整部剧的播出计划。')}}</p><div class="channels"><label v-for="(label,key) in {offline:'线下活动',live:'线上直播',drama:'剧集更新'}" :key="key"><input v-model="channels" type="checkbox" :value="key">{{tr(label)}}</label></div><p v-if="loadError" role="alert">{{tr('剧集日程暂时无法加载：')}}{{loadError}}</p><button v-for="row in visible" :key="row.calendarKey" class="personal-row" @click="emit('open',row)"><time>{{row.date}}<template v-if="row.end_date&&row.end_date!==row.date"> — {{row.end_date}}</template><small v-if="row.time">{{row.time}}</small></time><span>{{row.title||row.name}}<small>{{row.channel==='drama'?'EP.'+row.episode:activityLabel(row)}}</small></span></button><p v-if="!visible.length&&!loadError">{{tr('暂无符合筛选的个人日程。')}}</p><DramaMySubmissions/></section></template><style scoped>.channels{display:flex;flex-wrap:wrap;gap:16px;margin:20px 0;font-size:13px}.personal-row{width:100%;display:flex;gap:18px;text-align:left;background:transparent;color:inherit;border:0;border-bottom:1px solid #8797ab40;padding:14px 0;font:inherit;cursor:pointer}.personal-row time{font-size:12px;flex-shrink:0}.personal-row small{display:block;font-size:11px;opacity:.7;margin-top:4px}</style>
